namespace ghidra.file.formats.cabarc;





using ghidra.app.util.bin;
using ghidra.file.formats.sevenzip;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.factory;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

public class CabarcFileSystemFactory : GFileSystemFactoryByteProvider<CabarcFileSystem>, GFileSystemProbeBytesOnly {

	static readonly string CABARC_TMPFILE_PREFIX = "cabarc_tmp_";
	private static readonly byte[] CABARC_SIGNATURE_MAGIC =
		NumericUtilities.convertStringToBytes("4d53434600000000"); // "MSCF", 00000000

	private SevenZipCliToolWrapper cliTool;

	/* @Override */
	public int getBytesRequired() {
		return CABARC_SIGNATURE_MAGIC.length;
	}

	/* @Override */
	public bool probeStartBytes(FSRL containerFSRL, byte[] startBytes) {
		return Arrays.equals(startBytes, 0, CABARC_SIGNATURE_MAGIC.length, CABARC_SIGNATURE_MAGIC,
			0, CABARC_SIGNATURE_MAGIC.length);
	}

	/* @Override */
	public GFileSystem create(FSRLRoot targetFSRL, ByteProvider byteProvider,
			FileSystemService fsService, TaskMonitor monitor)
    {

		try {
			ensureTool(monitor);

			File archiveFile = fsService.getFileIfAvailable(byteProvider);
			File tmpFile = null;
			if (archiveFile == null) {
				archiveFile = tmpFile =
					fsService.createPlaintextTempFile(byteProvider, CABARC_TMPFILE_PREFIX, monitor);
			}

			CabarcFileSystem fs =
				new CabarcFileSystem(targetFSRL, fsService, cliTool, archiveFile, tmpFile);

			try {
				fs.mount(monitor);
				return fs;
			}
			catch (IOException e) {
				FSUtilities.uncheckedClose(fs, null);
				throw e;
			}
		}
		finally {
			FSUtilities.uncheckedClose(byteProvider, null);
		}
	}

	private void ensureTool(TaskMonitor monitor)
    {
		if (cliTool == null) {
			cliTool = SevenZipCliToolWrapper.findTool(monitor);
		}
		if (cliTool == null) {
			throw new FileSystemFactoryDependencyException("No 7z cli tool found in PATH");
		}
	}

}
